import "dotenv/config";
import OpenAI from "openai";

// Check API Key
if (!process.env.OPENROUTER_API_KEY) {
  console.error("❌ OPENROUTER_API_KEY is missing in .env");
}

const client = new OpenAI({
  apiKey: process.env.OPENROUTER_API_KEY,
  baseURL: "https://openrouter.ai/api/v1",
});

// =======================================
// AI Personal Finance Advisor
// =======================================
export const getAIAdvice = async (req, res) => {
  console.log("✅ AI API Endpoint Hit");

  try {
    const { question } = req.body;

    if (!question || question.trim() === "") {
      return res.status(400).json({
        success: false,
        message: "Question is required.",
      });
    }

    console.log("\n======================================");
    console.log("🧑 User Question:");
    console.log(question);
    console.log("======================================\n");

    const completion = await client.chat.completions.create({
      model: "meta-llama/llama-3.3-70b-instruct",

      messages: [
        {
          role: "system",
          content: `
You are FinanceHub AI.

You are an expert Personal Finance Advisor.

Your responsibilities:

- Answer only finance-related questions.
- Explain everything in simple English.
- Give practical advice.
- Suggest budgeting strategies.
- Recommend saving techniques.
- Explain investment basics.
- Help reduce unnecessary expenses.
- Never guarantee investment returns.
- Use bullet points whenever possible.
- Keep answers clear and beginner-friendly.
          `,
        },
        {
          role: "user",
          content: question,
        },
      ],

      temperature: 0.7,
      max_tokens: 700,
    });

    const aiResponse = completion.choices?.[0]?.message?.content;

    if (!aiResponse) {
      return res.status(500).json({
        success: false,
        message: "AI returned an empty response.",
      });
    }

    console.log("🤖 Llama Response");
    console.log("--------------------------------");
    console.log(aiResponse);
    console.log("--------------------------------");

    res.status(200).json({
      success: true,
      response: aiResponse,
    });

  } catch (error) {

    console.log("\n========== AI ERROR ==========\n");

    console.error("Message:", error.message);

    if (error.status) {
      console.error("Status:", error.status);
    }

    if (error.response) {
      console.error("Response:", error.response.data);
    }

    if (error.cause) {
      console.error("Cause:", error.cause);
    }

    console.error(error);

    console.log("\n==============================\n");

    res.status(500).json({
      success: false,
      message: error.message || "Failed to get AI response.",
    });
  }
};